def can_be_expressed_as_sum_of_two_cubes(n):
    """Check if n can be expressed as sum of two positive algebraic cubes."""
    cubes = []
    # Generate cubes up to n
    i = 1
    while i*i*i <= n:
        cubes.append(i*i*i)
        i += 1

    # Check all pairs of cubes
    ways = []
    for cube1 in cubes:
        if cube1 >= n:
            break
        diff = n - cube1
        # Check if diff is a cube (and positive)
        if diff > 0:
            cube2 = int(round(diff ** (1/3)))
            if cube2 > 0:
                if cube2 * cube2 * cube2 == diff:
                    ways.append((cube1, diff))

    return ways

def solve(n):
    """Find the closest number less than n which can be expressed as sum of two positive cubes in more than one way."""
    # Start from n-1 and go down
    for candidate in range(n-1, 0, -1):
        ways = can_be_expressed_as_sum_of_two_cubes(candidate)
        if len(ways) > 1:
            return candidate
    return -1

